<?php
require_once __DIR__.'/../../includes/auth.php';
require_once __DIR__.'/product_helpers.php';

$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['from']??'')?$_GET['from']:date('Y-m-01');
$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['to']??'')?$_GET['to']:date('Y-m-d');
if($from>$to){[$from,$to]=[$to,$from];}

$productSummary=$pdo->query("SELECT COUNT(*) total_products,SUM(status='active') active_products,COALESCE(SUM(CASE WHEN track_stock=1 THEN stock ELSE 0 END),0) total_stock,COALESCE(SUM(CASE WHEN track_stock=1 THEN stock*base_price ELSE 0 END),0) stock_base_value,COALESCE(SUM(CASE WHEN track_stock=1 THEN stock*selling_price ELSE 0 END),0) stock_sale_value FROM products")->fetch(PDO::FETCH_ASSOC);
$salesStmt=$pdo->prepare("SELECT COUNT(DISTINCT s.id) transactions,COALESCE(SUM(i.qty),0) qty_sold,COALESCE(SUM(i.net_amount),0) revenue,COALESCE(SUM(i.base_price*i.qty),0) base_total,COALESCE(SUM(i.profit_amount),0) profit FROM product_cashier_sales s JOIN product_cashier_sale_items i ON i.sale_id=s.id WHERE DATE(s.sale_date) BETWEEN :from AND :to AND s.payment_status='paid'");
$salesStmt->execute([':from'=>$from,':to'=>$to]);$salesSummary=$salesStmt->fetch(PDO::FETCH_ASSOC);
$products=$pdo->query("SELECT product_code,product_name,category,description,base_price,selling_price,stock,unit,track_stock,status FROM products ORDER BY product_name")->fetchAll(PDO::FETCH_ASSOC);
$detailStmt=$pdo->prepare("SELECT s.receipt_code,s.sale_date,s.customer_name,s.channel,s.payment_method,i.product_name,i.qty,i.unit_price,i.base_price,i.net_amount,i.profit_amount FROM product_cashier_sales s JOIN product_cashier_sale_items i ON i.sale_id=s.id WHERE DATE(s.sale_date) BETWEEN :from AND :to AND s.payment_status='paid' ORDER BY s.sale_date DESC,s.id DESC,i.id");
$detailStmt->execute([':from'=>$from,':to'=>$to]);$sales=$detailStmt->fetchAll(PDO::FETCH_ASSOC);

$pageTitle='Laporan Produk & POS - Nukari';
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';require_once __DIR__.'/_style.php';
?>
<main class="main-content"><div class="container-fluid product-page py-3"><?php require __DIR__.'/_nav.php';?>
<div class="page-header d-flex justify-content-between align-items-center flex-wrap gap-3"><div><h1 class="fw-bold mb-1">Laporan Produk & POS</h1><p class="text-muted mb-0">Produk jadi, penjualan, harga dasar, dan estimasi keuntungan.</p></div><div class="d-flex gap-2 no-print"><a class="btn btn-outline-success" href="export_excel.php?from=<?=urlencode($from);?>&to=<?=urlencode($to);?>"><i class="bi bi-file-earmark-excel me-1"></i>Export Excel</a><button class="btn btn-light" onclick="window.print()"><i class="bi bi-printer me-1"></i>Cetak</button></div></div>
<div class="product-card mb-3"><div class="card-body"><form class="row g-2 align-items-end"><div class="col-md-4"><label class="form-label">Dari</label><input type="date" name="from" value="<?=product_safe($from);?>" class="form-control"></div><div class="col-md-4"><label class="form-label">Sampai</label><input type="date" name="to" value="<?=product_safe($to);?>" class="form-control"></div><div class="col-md-4"><button class="btn btn-success">Terapkan Periode</button></div></form></div></div>
<div class="row g-3 mb-4"><div class="col-xl-3 col-md-6"><div class="kpi-card"><small>Produk Aktif</small><h3><?=(int)$productSummary['active_products'];?></h3><span class="text-muted">dari <?=(int)$productSummary['total_products'];?> produk</span></div></div><div class="col-xl-3 col-md-6"><div class="kpi-card"><small>Transaksi POS</small><h3><?=(int)$salesSummary['transactions'];?></h3><span class="text-muted"><?=product_num($salesSummary['qty_sold']);?> item terjual</span></div></div><div class="col-xl-3 col-md-6"><div class="kpi-card"><small>Omzet</small><h3><?=product_money($salesSummary['revenue']);?></h3><span class="text-muted"><?=product_safe($from);?> – <?=product_safe($to);?></span></div></div><div class="col-xl-3 col-md-6"><div class="kpi-card"><small>Estimasi Keuntungan</small><h3><?=product_money($salesSummary['profit']);?></h3><span class="text-muted">Omzet dikurangi harga dasar</span></div></div></div>
<div class="product-card mb-4"><div class="card-header bg-white"><strong>Produk Jadi</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Kode</th><th>Produk</th><th>Kategori</th><th class="text-end">Harga Dasar</th><th class="text-end">Harga Jual</th><th>Stok</th><th>Status</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=product_safe($p['product_code']);?></td><td><strong><?=product_safe($p['product_name']);?></strong><div class="small text-muted"><?=product_safe($p['description']?:'-');?></div></td><td><?=product_safe($p['category']?:'-');?></td><td class="text-end"><?=product_money($p['base_price']);?></td><td class="text-end fw-semibold text-success"><?=product_money($p['selling_price']);?></td><td><?=$p['track_stock']?product_num($p['stock']).' '.product_safe($p['unit']):'<span class="badge bg-info">Tanpa kontrol</span>';?></td><td><span class="badge <?=$p['status']==='active'?'bg-success':'bg-secondary';?>"><?=product_safe($p['status']);?></span></td></tr><?php endforeach;?><?php if(!$products):?><tr><td colspan="7" class="text-center text-muted py-4">Belum ada produk.</td></tr><?php endif;?></tbody></table></div></div>
<div class="product-card"><div class="card-header bg-white"><strong>Detail Penjualan POS</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Tanggal</th><th>Struk</th><th>Produk</th><th>Customer</th><th class="text-end">Qty</th><th class="text-end">Harga Jual</th><th class="text-end">Harga Dasar</th><th class="text-end">Net</th><th class="text-end">Keuntungan</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td><?=date('d M Y H:i',strtotime($s['sale_date']));?></td><td><?=product_safe($s['receipt_code']);?><div class="small text-muted"><?=product_safe($s['channel']);?> · <?=product_safe($s['payment_method']);?></div></td><td><?=product_safe($s['product_name']);?></td><td><?=product_safe($s['customer_name']?:'Umum');?></td><td class="text-end"><?=product_num($s['qty']);?></td><td class="text-end"><?=product_money($s['unit_price']);?></td><td class="text-end"><?=product_money($s['base_price']);?></td><td class="text-end fw-semibold"><?=product_money($s['net_amount']);?></td><td class="text-end text-success fw-semibold"><?=product_money($s['profit_amount']);?></td></tr><?php endforeach;?><?php if(!$sales):?><tr><td colspan="9" class="text-center text-muted py-4">Belum ada penjualan pada periode ini.</td></tr><?php endif;?></tbody></table></div></div>
</div></main><?php require_once __DIR__.'/../../includes/footer.php';?>
